export type LineupFactoryConfigFormat = typeof LineupFactoryConfigFormat[keyof typeof LineupFactoryConfigFormat];


export const LineupFactoryConfigFormat = {
  power: 'power',
  flex: 'flex',
  stack: 'stack',
  team_plus_player: 'team_plus_player',
} as const;

export type LineupFactoryConfigVarianceProfile = typeof LineupFactoryConfigVarianceProfile[keyof typeof LineupFactoryConfigVarianceProfile];


export const LineupFactoryConfigVarianceProfile = {
  conservative: 'conservative',
  balanced: 'balanced',
  aggressive: 'aggressive',
  chaos: 'chaos',
  custom: 'custom',
} as const;

export type LineupFactoryConfigOptimizationObjective = typeof LineupFactoryConfigOptimizationObjective[keyof typeof LineupFactoryConfigOptimizationObjective];


export const LineupFactoryConfigOptimizationObjective = {
  max_ev: 'max_ev',
  max_profit_prob: 'max_profit_prob',
  min_drawdown: 'min_drawdown',
  balanced_growth: 'balanced_growth',
  high_ceiling: 'high_ceiling',
} as const;

/**
 * fast=only include props from fast-pace matchups; neutral=exclude slow; any=no filter
 */
export type LineupFactoryConfigGppNarrativeFiltersPacePreference = typeof LineupFactoryConfigGppNarrativeFiltersPacePreference[keyof typeof LineupFactoryConfigGppNarrativeFiltersPacePreference];


export const LineupFactoryConfigGppNarrativeFiltersPacePreference = {
  fast: 'fast',
  neutral: 'neutral',
  any: 'any',
} as const;

/**
 * Optional GPP narrative context filters. Only applied when gppMode is true.
 */
export type LineupFactoryConfigGppNarrativeFilters = {
  /** Only include props from games with implied total above this threshold (e.g. 220 for NBA) */
  minGameTotal?: number;
  /** fast=only include props from fast-pace matchups; neutral=exclude slow; any=no filter */
  pacePreference?: LineupFactoryConfigGppNarrativeFiltersPacePreference;
  /** When true, exclude props where sharp money opposes the pick direction (sharpSignal=sharp_against) */
  sharpAlignmentOnly?: boolean;
};

export interface LineupFactoryConfig {
  format: LineupFactoryConfigFormat;
  /**
     * @minimum 2
     * @maximum 6
     */
  picksPerEntry: number;
  /**
     * @minimum 1
     * @maximum 25
     */
  numEntries: number;
  varianceProfile: LineupFactoryConfigVarianceProfile;
  optimizationObjective: LineupFactoryConfigOptimizationObjective;
  /** When true, applies GPP scoring (ceiling-first, ownership-leverage weighted) as an overlay on top of the selected optimizationObjective. Independent of the objective dropdown. */
  gppMode?: boolean;
  maxPlayerExposure: number;
  maxPickExposure: number;
  maxTeamExposure: number;
  maxGameExposure: number;
  maxPairwiseOverlap: number;
  /**
     * Max picks from the same team within a single lineup (null = unlimited)
     * @minimum 1
     * @maximum 6
     */
  maxPerTeam?: number | null;
  stakePerEntry: number;
  totalBudget?: number;
  minEdgeThreshold?: number;
  minProbabilityThreshold?: number;
  allowGtdPlayers: boolean;
  allowSingleBookData: boolean;
  allowStaleMarketData: boolean;
  demonUnderAllowed: boolean;
  sport?: string;
  /**
     * @minimum 1000
     * @maximum 50000
     */
  monteCarloIterations?: number;
  /** ppLineIds that must appear in every generated lineup */
  requiredLineIds?: number[];
  /**
     * Weight applied to personal bias delta when scoring props (0=off, 1=full weight). Nudges composite score by biasWeight × biasDelta so picks where the user historically outperforms the model rank higher.
     * @minimum 0
     * @maximum 1
     */
  biasWeight?: number;
  /** Optional GPP narrative context filters. Only applied when gppMode is true. */
  gppNarrativeFilters?: LineupFactoryConfigGppNarrativeFilters;
  /** When true, enables Story Mode — each lineup is built around a named game narrative template (Shootout Stack, Pace Exploit, etc.). Requires gppMode=true for full effect. */
  storyMode?: boolean;
  /** Template to use when storyMode is true. 'auto' distributes lineups across all templates; otherwise a specific template id (shootout, pace_exploit, grind, blowout, underdog). */
  storyTemplateId?: string;
  /**
     * Max proportion of lineups that can share the same story template (0–1, default 0.4). Only used when storyTemplateId=auto.
     * @minimum 0
     * @maximum 1
     */
  maxStoryConcentration?: number;
}

export type FactoryScoredPropDirection = typeof FactoryScoredPropDirection[keyof typeof FactoryScoredPropDirection];


export const FactoryScoredPropDirection = {
  more: 'more',
  less: 'less',
} as const;

/**
 * real = live crowd data from crowd_ownership_snapshots; estimated = tier-based fallback
 */
export type FactoryScoredPropOwnershipSource = typeof FactoryScoredPropOwnershipSource[keyof typeof FactoryScoredPropOwnershipSource];


export const FactoryScoredPropOwnershipSource = {
  real: 'real',
  estimated: 'estimated',
} as const;

export interface FactoryScoredProp {
  ppLineId: number;
  playerId: number;
  playerName: string;
  /** @nullable */
  imageUrl?: string | null;
  team: string;
  /** @nullable */
  teamId?: number | null;
  /** @nullable */
  gameId?: number | null;
  sport: string;
  statType: string;
  direction: FactoryScoredPropDirection;
  lineType: string;
  ppLine: number;
  payoutMultiplier?: number;
  hitProbability: number;
  probabilitySource: string;
  confidence: string;
  expectedValue: number;
  /** @nullable */
  edgeScore?: number | null;
  /** @nullable */
  riskScore?: number | null;
  /** @nullable */
  volatilityRating?: string | null;
  marketDataStatus: string;
  bookCount: number;
  /** @nullable */
  noPlayReason?: string | null;
  reasonCodes: string[];
  compositeScore: number;
  /**
     * Crowd ownership % (0–100). Real crowd data when available (ownershipSource=real), otherwise estimated from score tier and calibrated pOver
     * @nullable
     */
  ownershipEst?: number | null;
  /** real = live crowd data from crowd_ownership_snapshots; estimated = tier-based fallback */
  ownershipSource?: FactoryScoredPropOwnershipSource;
  /**
     * GPP leverage = ceiling-weighted EV / ownership_est; higher = contrarian upside
     * @nullable
     */
  leverageScore?: number | null;
  /**
     * fast / normal / slow — derived from the projection pace factor
     * @nullable
     */
  paceTier?: string | null;
  /**
     * Direction-aware sharp signal for this pick: sharp_for (smart money aligned with pick direction) / sharp_against (smart money opposes pick direction) / neutral
     * @nullable
     */
  sharpSignal?: string | null;
  /**
     * Implied game total from game_environment
     * @nullable
     */
  gameTotal?: number | null;
  /**
     * Proportion of generated lineups this prop appears in (0–1). Null before a run is generated.
     * @nullable
     */
  crowdingFreq?: number | null;
}

export interface FactoryLineupPick {
  ppLineId: number;
  playerId: number;
  playerName: string;
  /** @nullable */
  imageUrl?: string | null;
  statType: string;
  ppLine: number;
  payoutMultiplier?: number;
  direction: string;
  lineType: string;
  hitProbability: number;
  sport: string;
  /** @nullable */
  teamId?: number | null;
  /** @nullable */
  gameId?: number | null;
  compositeScore: number;
  /** @nullable */
  edgeScore?: number | null;
  /** @nullable */
  volatilityRating?: string | null;
  reasonCodes: string[];
}

export interface GeneratedLineup {
  id: number;
  picks: FactoryLineupPick[];
  format: string;
  picksPerEntry: number;
  ev: number;
  hitProbability: number;
  grossPayout: number;
  stake: number;
  correlationAdjusted: boolean;
  /** @nullable */
  correlationNote?: string | null;
  /** Top 2–3 dominant correlated player pairs in this lineup (e.g. 'LeBron James + Anthony Davis (+40%)'). Null when no meaningful correlation exists. */
  correlationPairs?: string[] | null;
  diversificationScore: number;
  /**
     * Story template id assigned to this lineup (e.g. 'shootout', 'pace_exploit'). Null when storyMode is off.
     * @nullable
     */
  storyTemplate?: string | null;
  /**
     * ppLineId of the anchor pick — the pick with highest narrative fit × ceiling / ownership for the assigned story.
     * @nullable
     */
  anchorPickId?: number | null;
  /** Simulated probability of hitting exactly k legs (index 0 = 0 hits, index n = all hits). Populated for Flex entries from Monte Carlo sim; null for Power entries. */
  hitCountProbabilities?: number[] | null;
  /** Probability of hitting zero legs (bust). For Flex: from Monte Carlo sim. For Power: 1 - hitProbability. */
  bustProbability: number;
}

